class Solution {
    public int rob(int[] nums) {
        return bestFrom(nums, 0);
    }

    private int bestFrom(int[] nums, int index) {
        if (index >= nums.length) return 0;
        int skip = bestFrom(nums, index + 1);
        int take = nums[index] + bestFrom(nums, index + 2);
        return Math.max(skip, take);
    }
}

